mapper.select:
select distinct e.code from sys_account a inner join sys_account_role b on b.account_id = a.id inner join sys_role c on c.id = b.role_id inner join sys_role_resource d on d.role_id = c.id inner join sys_resource e on e.id = d.resource_id where a.id = #{accountId,jdbcType=VARCHAR}
and a.deleted = 0 and b.deleted = 0 and c.deleted = 0 and d.deleted = 0 and e.deleted = 0
and c.enabled = 1 and e.enabled = 1
